const statuses: Record<string, string> = { issued: 'Выдан', accepted: 'Принят в работу', queued: 'В очереди', rejected: 'Отклонён', in_progress: 'В работе', paused: 'Приостановлен', completed: 'Исполнено', ai_review: 'Проверка ИИ', rework: 'На доработку', closed: 'Закрыт', cancelled: 'Отменён' };
